import React, { useEffect, useState } from "react";
import ArrowDropDownIcon from "@mui/icons-material/ArrowDropDown";
import http from "../../services/utility";
import { apisPath, paths } from "../../utils/path";
import { useNavigate } from "react-router-dom";
import AddIcon from "@mui/icons-material/Add";
import { openSuccessTicker } from "../../redux/reducer/SuccessTickerReducer";
import { openTicker } from "../../redux/reducer/ErrorTickerReducer";
import { useDispatch } from "react-redux";

export default function Offers() {
  const dispatch = useDispatch();
  const navigate = useNavigate();

  const [tableHeader, setTableHeader] = useState([
    { name: "Product" },
    { name: "Price" },
    // { name: "Purchased" },
    // { name: "Stock" },
    { name: "Expiry date" },
    { name: "Total Rating" },
  ]);

  const [offersData, setOffersData] = useState([
    // {
    //   title: "Buy 2 @ 15% Off",
    //   table: [
    //     {
    //       name: "product name",
    //       details: "details",
    //       image: "http://13.126.83.194/uploads/1700817112559.png",
    //       price: 500,
    //       purchased: 64,
    //       stock: 422,
    //       date: "10/12/2024",
    //     },
    //   ],
    // },
    // {
    //   title: "Pick of the Day",
    //   table: [
    //     {
    //       name: "product name",
    //       details: "details",
    //       image: "http://13.126.83.194/uploads/1700817112559.png",
    //       price: 500,
    //       purchased: 64,
    //       stock: 422,
    //       date: "10/12/2024",
    //     },
    //   ],
    // },
  ]);

  useEffect(() => {
    getData();
  }, []);

  const getData = async () => {
    await http
      .get(apisPath?.admin?.offers)
      .then(async (res) => {
        console.log(res?.data?.offers);
        setOffersData(res?.data?.offers);
      })
      .catch((err) => {
        console.log(err);
      });
  };

  const deleteOffer = async (index) => {
    await http
      .delete(`${apisPath?.admin?.offers}/${index}`)
      .then(async (res) => {
        // console.log(res?.data?.message);
        dispatch(
          openSuccessTicker({ title: "Success", body: res?.data?.message })
        );
        getData();
      })
      .catch((err) => {
        // console.log(err);
        dispatch(
          openTicker({ title: "Error", body: err?.response?.data?.message })
        );
      });
  };

  return (
    <div className="offers">
      <div className="offers__header">
        <h3 className="offers__heading page_heading">Offers</h3>
        <button
          className="button-red"
          onClick={() => navigate(`/${paths?.front?.user?.add_new_offer}`)}
        >
          <AddIcon /> Add new offer
        </button>
      </div>
      <div className="offers__content">
        {offersData?.length > 0 ? (
          offersData?.map((card, index) => {
            return (
              <div className="offers__content__card_container" key={index}>
                <h4>
                  <span>{card?.name}</span>
                  <button
                    className="button-red"
                    onClick={() => deleteOffer(card?.id)}
                  >
                    Delete
                  </button>
                </h4>
                <div className="offers__content__card_container__table">
                  <table className="offers__content__card_container__table__table">
                    <tr>
                      {tableHeader?.map((header, index) => {
                        return (
                          <th key={index}>
                            <span>
                              {header?.name} <ArrowDropDownIcon />
                            </span>
                          </th>
                        );
                      })}
                    </tr>
                    {card?.products?.map((data, index) => {
                      return (
                        <tr key={index}>
                          <td>
                            <div className="product div-flex">
                              {data?.images?.length > 0 && (
                                <img
                                  src={data?.images[0]}
                                  alt="Product Image"
                                />
                              )}
                              <div className="product__info">
                                <span>{data?.name}</span>
                                {/* <span>Details: {data?.details}</span> */}
                              </div>
                            </div>
                          </td>
                          <td>&#8377; {data?.varients[0]?.sellingPrice}</td>
                          {/* <td>{data?.purchased}</td>
                        <td>{data?.stock}</td> */}
                          <td>
                            {new Date(data?.createdAt)?.toLocaleString(
                              "en-US",
                              {
                                weekday: "short",
                                year: "numeric",
                                month: "short",
                                day: "numeric",
                                timeZone: "UTC",
                              }
                            )}
                          </td>
                          <td>{data?.totalRating}</td>
                        </tr>
                      );
                    })}
                  </table>
                </div>
              </div>
            );
          })
        ) : (
          <div className="no_data_found">No Data Found</div>
        )}
      </div>
    </div>
  );
}
